package com.howierux.mortalexpansion.gametest;
import com.howierux.mortalexpansion.catalog.*;
import com.howierux.mortalexpansion.content.ContentRuntime;
import com.howierux.mortalexpansion.machine.*;
import com.howierux.mortalexpansion.quest.*;
import com.howierux.mortalexpansion.fancifier.*;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import java.util.*;
public final class ContentSlicesGameTests implements FabricGameTest {
 private static net.minecraft.server.level.ServerPlayer player(GameTestHelper h){var cookie=net.minecraft.server.network.CommonListenerCookie.createInitial(new com.mojang.authlib.GameProfile(UUID.randomUUID(),"content-test"),false);var p=new net.minecraft.server.level.ServerPlayer(h.getLevel().getServer(),h.getLevel(),cookie.gameProfile(),cookie.clientInformation());var connection=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(connection);h.getLevel().getServer().getPlayerList().placeNewPlayer(connection,p,cookie);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setPos(h.absolutePos(new BlockPos(1,2,1)).getCenter());return p;}
 private static BlockPos at(GameTestHelper h,int x){return h.absolutePos(new BlockPos(x,2,3));}
 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void quests_pay_once_without_returning_to_spirit(GameTestHelper h){var p=player(h);try{var q=new SpiritQuest("test",net.minecraft.resources.ResourceLocation.parse("minecraft:zombie"),1,0,2,"Departed",Long.MAX_VALUE);p.setAttached(ContentRuntime.QUESTS,new SpiritQuestState(Optional.of(q),Optional.empty(),0));h.assertTrue(!SpiritQuests.accept(p,"forged")&&SpiritQuests.accept(p,"test"),"Only issued offer may be accepted");h.assertTrue(!SpiritQuests.credit(p,net.minecraft.world.entity.EntityType.COW),"Unrelated kills give no credit");var z=net.minecraft.world.entity.EntityType.ZOMBIE.create(h.getLevel());SpiritQuests.killed(z,h.getLevel().damageSources().playerAttack(p));h.assertTrue(SpiritQuests.state(p).active().isEmpty()&&p.getInventory().countItem(Items.EMERALD)==4&&p.totalExperience==40,"Kill event delivers rewards immediately");SpiritQuests.killed(z,h.getLevel().damageSources().playerAttack(p));h.assertTrue(p.getInventory().countItem(Items.EMERALD)==4,"Duplicate completion cannot pay again");h.succeed();}finally{h.getLevel().getServer().getPlayerList().remove(p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void spirit_menu_rejects_replay_and_distance(GameTestHelper h){var p=player(h);try{var spirit=com.howierux.mortalexpansion.entity.CombatEntities.SPIRIT.create(h.getLevel());spirit.setPos(p.position().add(1,0,0));h.getLevel().addFreshEntity(spirit);String token=SpiritInteraction.open(p,spirit);h.assertTrue(!token.isEmpty()&&SpiritInteraction.choose(p,token,1),"Nearby player opens unfinished business");h.assertTrue(!SpiritInteraction.choose(p,token,1),"Consumed session cannot replay");String fresh=SpiritInteraction.token(p);p.setPos(p.position().add(30,0,0));h.assertTrue(!SpiritInteraction.choose(p,fresh,2)&&SpiritQuests.state(p).active().isEmpty(),"Walking away invalidates acceptance");h.succeed();}finally{h.getLevel().getServer().getPlayerList().remove(p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void grave_worker_reverts_with_inventory_on_break(GameTestHelper h){var p=player(h);try{var pos=at(h,3);h.getLevel().setBlockAndUpdate(pos,CatalogBlocks.GRAVE.defaultBlockState());var grave=(com.howierux.mortalexpansion.travel.GraveEntity)h.getLevel().getBlockEntity(pos);grave.placed(p);grave.name(p,"Villager");var v=net.minecraft.world.entity.EntityType.VILLAGER.create(h.getLevel());v.setPos(pos.getCenter().add(2,0,0));v.getInventory().setItem(0,new ItemStack(Items.BREAD,5));h.getLevel().addFreshEntity(v);var spirit=com.howierux.mortalexpansion.entity.mob.SpiritWorkstations.convert(h.getLevel(),grave,v);h.assertTrue(spirit!=null&&spirit.graveCreated()&&spirit.getInventory().getItem(0).getCount()==5,"Grave conversion preserves native inventory");h.getLevel().destroyBlock(pos,false);var restored=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.npc.Villager.class,spirit.getBoundingBox().inflate(2));h.assertTrue(restored.stream().anyMatch(x->x.getVillagerData().getProfession()==net.minecraft.world.entity.npc.VillagerProfession.NONE&&x.getInventory().getItem(0).getCount()==5),"Broken grave restores jobless villager");h.succeed();}finally{h.getLevel().getServer().getPlayerList().remove(p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void golem_requires_sixteen_flesh_and_clearance(GameTestHelper h){var base=at(h,3);h.getLevel().setBlockAndUpdate(base,CatalogBlocks.MORTAL_GOLEM_BASE.defaultBlockState());var frame=(com.howierux.mortalexpansion.blockentity.MortalGolemBaseBlockEntity)h.getLevel().getBlockEntity(base);frame.addFlesh(15);h.getLevel().setBlockAndUpdate(base.above(),CatalogBlocks.WISP_O_LANTERN.defaultBlockState());h.assertTrue(!com.howierux.mortalexpansion.haunt.MortalGolemFormation.tryForm(h.getLevel(),base.above()),"Fifteen flesh cannot form");frame.addFlesh(1);h.getLevel().setBlockAndUpdate(base.above(2),Blocks.STONE.defaultBlockState());h.assertTrue(!com.howierux.mortalexpansion.haunt.MortalGolemFormation.tryForm(h.getLevel(),base.above())&&frame.flesh()==16,"Blocked construction preserves materials");h.getLevel().removeBlock(base.above(2),false);h.assertTrue(com.howierux.mortalexpansion.haunt.MortalGolemFormation.tryForm(h.getLevel(),base.above()),"Existing lantern forms after sixteenth flesh");h.assertTrue(h.getLevel().getBlockState(base).isAir(),"Successful formation consumes frame");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void regeneration_forms_carved_head_only(GameTestHelper h){var base=at(h,3);h.getLevel().setBlockAndUpdate(base,CatalogBlocks.MORTAL_GOLEM_BASE.defaultBlockState());((com.howierux.mortalexpansion.blockentity.MortalGolemBaseBlockEntity)h.getLevel().getBlockEntity(base)).addFlesh(32);h.getLevel().setBlockAndUpdate(base.above(),Blocks.CARVED_PUMPKIN.defaultBlockState());var potion=new ItemStack(Items.SPLASH_POTION);potion.set(net.minecraft.core.component.DataComponents.POTION_CONTENTS,new net.minecraft.world.item.alchemy.PotionContents(net.minecraft.world.item.alchemy.Potions.REGENERATION));com.howierux.mortalexpansion.haunt.MortalGolemFormation.regeneration(h.getLevel(),potion,base.above().getCenter());h.assertTrue(h.getLevel().getBlockState(base).isAir(),"Regeneration forms eligible carved-pumpkin frame");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void ectchantment_transactions_persistence_and_blocked_output(GameTestHelper h){var pos=at(h,2);h.getLevel().setBlockAndUpdate(pos,CatalogBlocks.ECTCHANTMENT_MACHINE.defaultBlockState());var be=(EctchantmentEntity)h.getLevel().getBlockEntity(pos);be.setItem(0,new ItemStack(Items.DIAMOND,2));be.setItem(1,new ItemStack(CatalogItems.PURE_ECTOPLASM));be.setItem(2,new ItemStack(Items.DIRT,64));be.tick();h.assertTrue(be.charge()==4000&&be.getItem(0).getCount()==2,"Blocked output does not spend charge or input");be.setItem(2,ItemStack.EMPTY);be.tick();h.assertTrue(be.getItem(2).is(CatalogItems.BLOODSTONE)&&be.charge()==0,"Purified charge performs native transformation");try(var tx=net.fabricmc.fabric.api.transfer.v1.transaction.Transaction.openOuter()){be.energy.insert(4000,tx);}h.assertTrue(be.energy.amount==0,"Aborted power insert rolls back");be.energy.amount=40000;var tag=be.saveWithFullMetadata(h.getLevel().registryAccess());var restored=(EctchantmentEntity)net.minecraft.world.level.block.entity.BlockEntity.loadStatic(pos,be.getBlockState(),tag,h.getLevel().registryAccess());h.assertTrue(restored.energy.amount==40000&&restored.getItem(0).getCount()==1,"Native NBT retains energy and inventory");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void fancifier_preserves_stack_components_and_boundaries(GameTestHelper h){var p=player(h);try{var pos=at(h,2);h.getLevel().setBlockAndUpdate(pos,CatalogBlocks.FANCIFIER.defaultBlockState());var menu=new com.howierux.mortalexpansion.menu.FancifierMenu(7,p.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.create(h.getLevel(),pos));p.setPos(pos.getCenter());var in=new ItemStack(Items.CHEST,8);in.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Keepsake"));menu.getSlot(0).set(in);h.assertTrue(!menu.clickMenuButton(p,101)&&!menu.clickMenuButton(p,-1)&&menu.clickMenuButton(p,1)&&menu.clickMenuButton(p,0),"Only 1-100 accepted and 1% can apply");var out=menu.getSlot(1).getItem();h.assertTrue(out.getCount()==8&&FancifierRules.opacity(out)==1&&out.getHoverName().getString().equals("Keepsake"),"Output preserves count and components");var restored=FancifierRules.convert(out,100,p.registryAccess());h.assertTrue(!restored.has(ContentRuntime.FADING)&&restored.getHoverName().getString().equals("Keepsake"),"100% restores original item");menu.removed(p);h.assertTrue(p.getInventory().countItem(Items.CHEST)==8,"Closing returns contents");h.succeed();}finally{h.getLevel().getServer().getPlayerList().remove(p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void fading_keeps_functional_block_identity_and_drop_metadata(GameTestHelper h){var pos=at(h,3);h.getLevel().setBlockAndUpdate(pos,Blocks.CHEST.defaultBlockState());var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)h.getLevel().getBlockEntity(pos);chest.setItem(0,new ItemStack(Items.DIAMOND,5));FadingWorld.set(h.getLevel(),pos,20);h.getLevel().setBlockAndUpdate(pos,h.getLevel().getBlockState(pos).setValue(ChestBlock.FACING,Direction.EAST));h.assertTrue(FadingWorld.opacity(h.getLevel(),pos)==20&&h.getLevel().getBlockEntity(pos)==chest&&chest.getItem(0).getCount()==5,"State updates preserve native chest inventory and opacity");var drops=Block.getDrops(h.getLevel().getBlockState(pos),h.getLevel(),pos,chest);h.assertTrue(drops.stream().anyMatch(x->x.is(Items.CHEST)&&FancifierRules.opacity(x)==20),"Native block drops retain opacity");h.getLevel().removeBlock(pos,false);h.assertTrue(FadingWorld.opacity(h.getLevel(),pos)==100,"Removal clears metadata");h.getLevel().setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());h.assertTrue(FadingWorld.opacity(h.getLevel(),pos)==100,"Replacement cannot inherit stale opacity");h.succeed();}

 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void flesh_application_costs_one_and_wisp_conversion_obeys_time(GameTestHelper h){var p=player(h);try{var pos=at(h,2);h.getLevel().setBlockAndUpdate(pos,Blocks.BONE_BLOCK.defaultBlockState());p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.ROTTEN_FLESH,64));var hit=new net.minecraft.world.phys.BlockHitResult(pos.getCenter(),Direction.UP,pos,false);com.howierux.mortalexpansion.haunt.MortalGolemFormation.apply(p,h.getLevel(),net.minecraft.world.InteractionHand.MAIN_HAND,hit);h.assertTrue(p.getMainHandItem().getCount()==63&&((com.howierux.mortalexpansion.blockentity.MortalGolemBaseBlockEntity)h.getLevel().getBlockEntity(pos)).flesh()==1,"One click consumes and applies exactly one flesh");var pumpkin=at(h,5);h.getLevel().setBlockAndUpdate(pumpkin,Blocks.CARVED_PUMPKIN.defaultBlockState());com.howierux.mortalexpansion.haunt.HauntManager.setValue(h.getLevel(),pumpkin,30);long old=h.getLevel().getDayTime();try{h.getLevel().setDayTime(6000);h.assertTrue(!com.howierux.mortalexpansion.haunt.WispLanternConversion.convert(h.getLevel(),pumpkin),"Daylight prevents Wisp conversion");h.getLevel().setDayTime(18000);h.assertTrue(com.howierux.mortalexpansion.haunt.WispLanternConversion.convert(h.getLevel(),pumpkin),"Eligible night conversion succeeds");h.assertTrue(com.howierux.mortalexpansion.haunt.HauntManager.getValue(h.getLevel(),pumpkin)==29,"Conversion consumes one chunk Haunt");var drops=Block.getDrops(h.getLevel().getBlockState(pumpkin),h.getLevel(),pumpkin,h.getLevel().getBlockEntity(pumpkin));h.assertTrue(drops.stream().anyMatch(x->x.is(Items.CARVED_PUMPKIN))&&drops.stream().anyMatch(x->x.is(CatalogItems.RAW_ECTOPLASM)),"Ordinary breaking drops pumpkin and ectoplasm");}finally{h.getLevel().setDayTime(old);}h.succeed();}finally{h.getLevel().getServer().getPlayerList().remove(p);}}

 @GameTest(template=EMPTY_STRUCTURE,batch="content") public void faded_native_placement_and_piston_transfer(GameTestHelper h){var p=player(h);try{var support=at(h,2);h.getLevel().setBlockAndUpdate(support,Blocks.STONE.defaultBlockState());var chest=new ItemStack(Items.CHEST);chest.set(ContentRuntime.FADING,37);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,chest);var hit=new net.minecraft.world.phys.BlockHitResult(support.getCenter().add(0,.5,0),Direction.UP,support,false);var result=chest.useOn(new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,hit));h.assertTrue(result.consumesAction()&&h.getLevel().getBlockState(support.above()).is(Blocks.CHEST)&&FadingWorld.opacity(h.getLevel(),support.above())==37,"Native item placement keeps chest identity and opacity component");}finally{h.getLevel().getServer().getPlayerList().remove(p);}var piston=at(h,5);h.getLevel().setBlockAndUpdate(piston,Blocks.PISTON.defaultBlockState().setValue(net.minecraft.world.level.block.piston.PistonBaseBlock.FACING,Direction.EAST));h.getLevel().setBlockAndUpdate(piston.east(),Blocks.STONE.defaultBlockState());FadingWorld.set(h.getLevel(),piston.east(),23);h.getLevel().setBlockAndUpdate(piston.west(),Blocks.REDSTONE_BLOCK.defaultBlockState());h.runAfterDelay(8,()->{h.assertTrue(h.getLevel().getBlockState(piston.east(2)).is(Blocks.STONE)&&FadingWorld.opacity(h.getLevel(),piston.east(2))==23,"Native piston transfers faded block metadata");h.assertTrue(FadingWorld.opacity(h.getLevel(),piston.east())==100,"Piston head cannot inherit moved block opacity");h.succeed();});}
}
